    public Object parseTrade(Object trade, Map<String, Object> market)
    {
        //
        // fetchTrades
        //     [
        //         {
        //             "tradeId": "100178000000367159",
        //             "symbol": "BTCUSDC",
        //             "price": "103891.8977",
        //             "quantity": "0.00029411",
        //             "quoteAmount": "30.5556",
        //             "side": "BUY",
        //             "isTaker": true,
        //             "createdAtTimestamp": "1747768055826",
        //             "createdAtDatetime": "2025-05-20T19:07:35.826Z"
        //         }, ...
        //     ]
        //
        //     [
        //         {
        //             "tradeId": "100020000000000060",
        //             "symbol": "BTCUSDC",
        //             "price": "1.00000000",
        //             "quantity": "1.00000000",
        //             "side": "BUY",
        //             "isTaker": true,
        //             "createdAtDatetime": "2021-05-20T01:01:01.000Z",
        //             "createdAtTimestamp": "1621490985000"
        //         }
        //     ]
        //
        // fetchMyTrades
        //     [
        //         {
        //             "baseFee": "0.00000000",
        //             "createdAtDatetime": "2025-05-18T15:57:28.132Z",
        //             "createdAtTimestamp": "1747583848132",
        //             "handle": null,
        //             "isTaker": true,
        //             "orderId": "844242293909618689",
        //             "price": "103942.7048",
        //             "publishedAtTimestamp": "1747769786131",
        //             "quantity": "1.00000000",
        //             "quoteAmount": "103942.7048",
        //             "quoteFee": "0.0000",
        //             "side": "BUY",
        //             "symbol": "BTCUSDC",
        //             "tradeId": "100178000000288892"
        //         }, ...
        //     ]
        //
        String marketId = this.safeString(trade, "symbol");
        market = (Map<String, Object>) (this.safeMarket(marketId, market));
        Object symbol = ((Map<String, Object>)market).get("symbol");
        Long timestamp = this.safeInteger(trade, "createdAtTimestamp");
        String price = this.safeString(trade, "price");
        String amount = this.safeString(trade, "quantity");
        String side = this.safeStringLower(trade, "side");
        Boolean isTaker = (Boolean) this.safeBool(trade, "isTaker");
        Object currency = ((Map<String, Object>)market).get("quote");
        String code = this.safeCurrencyCode((String) (currency));
        Double feeCost = this.safeNumber(trade, "quoteFee");
        Object fee = null;
        if (!java.util.Objects.equals(feeCost, null))
        {
            final Double finalFeeCost = feeCost;
            fee = new HashMap<String, Object>() {{
                put( "currency", code );
                put( "cost", finalFeeCost );
            }};
        }
        String takerOrMaker = null;
        if (java.util.Objects.equals(isTaker, true))
        {
            takerOrMaker = "taker";
        } else
        {
            takerOrMaker = "maker";
        }
        String orderId = this.safeString(trade, "orderId");
        final String finalTakerOrMaker = takerOrMaker;
        final Object finalFee = fee;
        return this.safeTrade((Map<String, Object>) (new HashMap<String, Object>() {{
            put( "info", trade );
            put( "timestamp", timestamp );
            put( "datetime", Bullish.this.iso8601(timestamp) );
            put( "symbol", symbol );
            put( "id", Bullish.this.safeString(trade, "tradeId") );
            put( "order", orderId );
            put( "type", null );
            put( "takerOrMaker", finalTakerOrMaker );
            put( "side", side );
            put( "price", price );
            put( "amount", amount );
            put( "cost", null );
            put( "fee", finalFee );
        }}), market);
    }
